// XOR Relief - terraces of popcount(x XOR y) with a fake bevel, seam-free.
// Parametric (u,v) texture, static (fixed light).
//
// Height of a cell = number of 1 bits in x XOR y (Hamming distance between the
// two indices): a stepped, self-similar landscape. Like Porous Bone, the relief
// is painted: each cell compares its height with its 4 neighbours and lights
// or shades the walls that drop toward them.
// SEAM-FREE: power-of-two grid with wrapped indices (neighbours wrap too) ->
// no jump at u = 0/1 or v = 0/1. Twisted gluing (Klein bottle, Moebius
// band): set MIRROR_V to 1.0. Seam-free with any pan, zoom 1, 1/2, 1/4...
// Dock colors: u_col1 = high terraces, u_col2 = low terraces.

const int   BITS        = 6;     // 2^BITS cells per turn            [4 .. 8]
const float WALL        = 0.22;  // wall width, fraction of a cell   [0.05 .. 0.45]
const float RELIEF      = 0.9;   // strength of the painted relief   [0 .. 2]
const float CONTRAST    = 1.6;   // spread of the terrace colors     [0.5 .. 3]
const float LIGHT_ANGLE = 0.375; // direction of the light, in turns   [0 .. 1]
const vec2  SHIFT     = vec2(0.3183, 0.2071); // moves the strongest lines of the
                                         // pattern off the seams (any value works)
const float MIRROR_U    = 0.0;   // 1 = fold u
const float MIRROR_V    = 0.0;   // 1 = fold v (Klein bottle, Moebius band)

vec2 seamFold(vec2 q) {
    vec2 tri = 0.5 - abs(fract(q) - 0.5);
    return mix(q, tri, vec2(MIRROR_U, MIRROR_V));
}

float terrace(ivec2 c, int m) {
    c &= m;
    int v = c.x ^ c.y;
    int bits = 0;
    for (int b = 0; b < BITS; b++) bits += (v >> b) & 1;
    return float(bits) / float(BITS);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 raw = fragCoord / iResolution.xy;
    vec2 uv = seamFold(raw) + SHIFT;

    int n = 1 << BITS;
    int m = n - 1;
    vec2 p = uv * float(n);
    ivec2 c = ivec2(floor(p));
    vec2 f = fract(p);

    float h  = terrace(c, m);
    float hl = terrace(c + ivec2(-1, 0), m);
    float hr = terrace(c + ivec2( 1, 0), m);
    float hd = terrace(c + ivec2(0, -1), m);
    float hu = terrace(c + ivec2(0,  1), m);

    // To make the light turn, write TAU * (LIGHT_ANGLE + iTime * 0.08): one
    // turn every 12.5 s, and the texture becomes animated (Run/Stop).
    float ang = TAU * LIGHT_ANGLE;
    vec2 L = vec2(cos(ang), sin(ang));

    // a wall drops from this cell toward a lower neighbour: its slope faces
    // the neighbour, so it is lit when that direction faces the light
    float shade = 0.0;
    shade += max(h - hl, 0.0) * (1.0 - smoothstep(0.0, WALL, f.x))       * dot(vec2(-1.0, 0.0), L);
    shade += max(h - hr, 0.0) * (1.0 - smoothstep(0.0, WALL, 1.0 - f.x)) * dot(vec2( 1.0, 0.0), L);
    shade += max(h - hd, 0.0) * (1.0 - smoothstep(0.0, WALL, f.y))       * dot(vec2(0.0, -1.0), L);
    shade += max(h - hu, 0.0) * (1.0 - smoothstep(0.0, WALL, 1.0 - f.y)) * dot(vec2(0.0,  1.0), L);
    // the foot of a wall rising from this cell gets a soft contact shadow
    float foot = max(hl - h, 0.0) * (1.0 - smoothstep(0.0, WALL, f.x))
               + max(hr - h, 0.0) * (1.0 - smoothstep(0.0, WALL, 1.0 - f.x))
               + max(hd - h, 0.0) * (1.0 - smoothstep(0.0, WALL, f.y))
               + max(hu - h, 0.0) * (1.0 - smoothstep(0.0, WALL, 1.0 - f.y));

    float k = clamp(0.5 + (h - 0.5) * CONTRAST, 0.0, 1.0);
    vec3 col = mix(u_col2, u_col1, k);
    col *= 1.0 + RELIEF * 1.5 * shade;
    col *= 1.0 - 0.6 * RELIEF * min(foot * 2.0, 1.0);

    // cells smaller than a pixel: average color instead of moire
    vec2 fw = min(fwidth(raw), fwidth(fract(raw + 0.5))) * float(n);
    col = mix(col, mix(u_col1, u_col2, 0.5), smoothstep(0.7, 2.0, max(fw.x, fw.y)));

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
